扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: import { readFileSync, readdirSync } from 'node:fs';
L2: import { dirname, join } from 'node:path';
L3: import { fileURLToPath } from 'node:url';
L4: 
L5: const root = join(dirname(fileURLToPath(import.meta.url)), '..');
L6: const live = process.argv.includes('--live');
L7: const timeoutMs = 8000;
L8: 
L9: function strategyUrls() {
L10:   const dir = join(root, 'strategies');
L11:   const urls = [];
L12:   for (const file of readdirSync(dir).filter((name) => name.endsWith('.md')).sort()) {
L13:     const text = readFileSync(join(dir, file), 'utf8');
L14:     for (const match of text.matchAll(/https?:\/\/[^\s)]+/g)) {
L15:       urls.push({ file, url: match[0] });
L16:     }
L17:   }
L18:   return urls;
L19: }
L20: 
L21: async function fetchWithTimeout(url, method) {
L22:   const controller = new AbortController();
L23:   const timer = setTimeout(() => controller.abort(), timeoutMs);
L24:   try {
L25:     return await fetch(url, { method, redirect: 'follow', signal: controller.signal });
L26:   } finally {
L27:     clearTimeout(timer);
L28:   }
L29: }
L30: 
L31: async function checkUrl(item) {
L32:   try {
L33:     let response = await fetchWithTimeout(item.url, 'HEAD');
L34:     if ([403, 405].includes(response.status)) {
L35:       response = await fetchWithTimeout(item.url, 'GET');
L36:     }
L37:     if ([404, 410].includes(response.status) || response.status >= 500) {
L38:       return { ...item, status: response.status, level: 'error' };
L39:     }
L40:     if ([401, 403, 429].includes(response.status)) {
L41:       return { ...item, status: response.status, level: 'warning' };
L42:     }
L43:     return { ...item, status: response.status, level: 'ok' };
L44:   } catch (error) {
L45:     return { ...item, status: error.name, level: 'warning' };
L46:   }
L47: }
